<header class="page-hero"><p class="eyebrow">Your selection</p><h1>Shopping bag</h1></header><section class="section container"><?php if (!$cart['items']): ?><div class="empty"><h2>Your bag is empty.</h2><a class="button" href="<?= e(url('/shop')) ?>">Explore the shop</a></div><?php else: ?><div class="cart-layout"><form method="post" action="<?= e(url('/cart/update')) ?>"><?= csrf_field() ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Total</th></tr></thead><tbody><?php foreach ($cart['items'] as $item): ?><tr><td><a href="<?= e(url('/product/'.$item['slug'])) ?>"><strong><?= e($item['name']) ?></strong></a></td><td><?= money($item['unit_price']) ?></td><td><input aria-label="Quantity for <?= e($item['name']) ?>" type="number" min="0" max="99" name="qty[<?= (int)$item['id'] ?>]" value="<?= (int)$item['quantity'] ?>"></td><td><?= money($item['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div><button>Update bag</button></form><aside class="summary"><h2>Order summary</h2><p>Subtotal <strong><?= money($cart['subtotal']) ?></strong></p><p class="muted">Shipping is confirmed after review.</p><a class="button alt" href="<?= e(url('/checkout')) ?>">Checkout</a></aside></div><?php endif; ?></section>

